"""Sortie ZF2, batch 6: the primitive character (Mathlib primitiveCharacter),
its properties, the finite set of primitive characters, the injectivity of
inducing primitive characters (LargeSieve) and Census prodChar_ne_one."""
import sys, os; sys.path.insert(0, os.path.join(os.path.dirname(__file__), '..')); from tm import *
from zf2lib import *
only = sys.argv[1:]
def run(w):
    if only and w.label not in only: return True
    return w.run()

HC = '( N e. NN /\\ X e. %s )' % DB('N')
C = COND('N', 'X'); CS = CSET('N', 'X'); P = PRIM('N', 'X'); PB = PRIMBODY('N', 'X')
def BODY(d, n, x): return '( %s || %s /\\ E. y e. %s %s = %s )' % (d, n, DB(d), x, IND(d, n, 'y'))
def hcond(w, ante, hc):
    """C e. NN, C || N from hc: ( ante -> HC )"""
    return (w.s([hc, w.inst('dchrcondnn')], 'syl', '( %s -> %s e. NN )' % (ante, C)),
            w.s([hc, w.inst('dchrconddvdn')], 'syl', '( %s -> %s || N )' % (ante, C)))

# ---- dchrprimval
w = W('dchrprimval', 'Value of the primitive character (Mathlib primitiveCharacter): the unique character mod the conductor inducing X.')
n = w.s([], 'simpl', '( %s -> N e. NN )' % HC); x = w.s([], 'simpr', '( %s -> X e. %s )' % (HC, DB('N')))
d0 = w.s([], 'df-dchrprim', 'DChrPrim = ( n e. NN , x e. %s |-> %s )' % (DB('n'), PRIMBODY('n', 'x')))
d1 = w.s([d0], 'a1i', '( %s -> DChrPrim = ( n e. NN , x e. %s |-> %s ) )' % (HC, DB('n'), PRIMBODY('n', 'x')))
A2 = '( %s /\\ ( n = N /\\ x = X ) )' % HC
ln = w.s([], 'simprl', '( %s -> n = N )' % A2); lx = w.s([], 'simprr', '( %s -> x = X )' % A2)
cc = w.s([ln, lx], 'oveq12d', '( %s -> %s = %s )' % (A2, COND('n', 'x'), C))
dcc = w.s([w.s([cc], 'fveq2d', '( %s -> ( DChr ` %s ) = ( DChr ` %s ) )' % (A2, COND('n', 'x'), C))], 'fveq2d', '( %s -> %s = %s )' % (A2, DB(COND('n', 'x')), DB(C)))
op = w.s([cc, ln], 'oveq12d', '( %s -> %s = %s )' % (A2, INDOP(COND('n', 'x'), 'n'), INDOP(C, 'N')))
iv = w.s([op], 'fveq1d', '( %s -> %s = %s )' % (A2, IND(COND('n', 'x'), 'n', 'y'), IND(C, 'N', 'y')))
bi = w.s([lx, iv], 'eqeq12d', '( %s -> ( x = %s <-> X = %s ) )' % (A2, IND(COND('n', 'x'), 'n', 'y'), IND(C, 'N', 'y')))
ri = w.s([dcc, bi], 'riotaeqbidv', '( %s -> %s = %s )' % (A2, PRIMBODY('n', 'x'), PB))
A1 = '( %s /\\ n = N )' % HC
dom = w.s([w.s([w.s([], 'simpr', '( %s -> n = N )' % A1)], 'fveq2d', '( %s -> ( DChr ` n ) = ( DChr ` N ) )' % A1)], 'fveq2d', '( %s -> %s = %s )' % (A1, DB('n'), DB('N')))
ex = w.s([w.s([], 'riotaex', '%s e. _V' % PB)], 'a1i', '( %s -> %s e. _V )' % (HC, PB))
w.qed([d1, ri, dom, n, x, ex], 'ovmpodx', '( %s -> %s = %s )' % (HC, P, PB)); run(w)

# ---- dchrprimeu: unique existence
EU = 'E! y e. %s X = %s' % (DB(C), IND(C, 'N', 'y'))
w = W('dchrprimeu', 'There is exactly one character mod the conductor inducing X (existence from dchrcondex, uniqueness from dchrindinj).')
n = w.s([], 'simpl', '( %s -> N e. NN )' % HC); x = w.s([], 'simpr', '( %s -> X e. %s )' % (HC, DB('N')))
ex = w.s([], 'dchrcondex', '( %s -> E. y e. %s X = %s )' % (HC, DB(C), IND(C, 'N', 'y')))
cn, cd = hcond(w, HC, w.s([], 'id', '( %s -> %s )' % (HC, HC)))
A2 = '( %s /\\ ( y e. %s /\\ z e. %s ) )' % (HC, DB(C), DB(C)); A3 = '( %s /\\ ( X = %s /\\ X = %s ) )' % (A2, IND(C, 'N', 'y'), IND(C, 'N', 'z'))
eq = w.s([w.s([], 'simprl', '( %s -> X = %s )' % (A3, IND(C, 'N', 'y'))), w.s([], 'simprr', '( %s -> X = %s )' % (A3, IND(C, 'N', 'z')))], 'eqtr3d', '( %s -> %s = %s )' % (A3, IND(C, 'N', 'y'), IND(C, 'N', 'z')))
h3 = w.s([w.s([cn], 'ad2antrr', '( %s -> %s e. NN )' % (A3, C)), w.s([n], 'ad2antrr', '( %s -> N e. NN )' % A3), w.s([cd], 'ad2antrr', '( %s -> %s || N )' % (A3, C))], '3jca', '( %s -> ( %s e. NN /\\ N e. NN /\\ %s || N ) )' % (A3, C, C))
inj = w.s([h3, w.s([w.s([], 'simprl', '( %s -> y e. %s )' % (A2, DB(C)))], 'adantr', '( %s -> y e. %s )' % (A3, DB(C))), w.s([w.s([], 'simprr', '( %s -> z e. %s )' % (A2, DB(C)))], 'adantr', '( %s -> z e. %s )' % (A3, DB(C))), w.inst('dchrindinj')], 'syl3anc', '( %s -> ( %s = %s <-> y = z ) )' % (A3, IND(C, 'N', 'y'), IND(C, 'N', 'z')))
yz = w.s([eq, inj], 'mpbid', '( %s -> y = z )' % A3)
yz2 = w.s([yz], 'ex', '( %s -> ( ( X = %s /\\ X = %s ) -> y = z ) )' % (A2, IND(C, 'N', 'y'), IND(C, 'N', 'z')))
al = w.s([yz2], 'ralrimivva', '( %s -> A. y e. %s A. z e. %s ( ( X = %s /\\ X = %s ) -> y = z ) )' % (HC, DB(C), DB(C), IND(C, 'N', 'y'), IND(C, 'N', 'z')))
sb = w.s([w.s([], 'fveq2', '( y = z -> %s = %s )' % (IND(C, 'N', 'y'), IND(C, 'N', 'z')))], 'eqeq2d', '( y = z -> ( X = %s <-> X = %s ) )' % (IND(C, 'N', 'y'), IND(C, 'N', 'z')))
r4 = w.s([sb], 'reu4', '( %s <-> ( E. y e. %s X = %s /\\ A. y e. %s A. z e. %s ( ( X = %s /\\ X = %s ) -> y = z ) ) )' % (EU, DB(C), IND(C, 'N', 'y'), DB(C), DB(C), IND(C, 'N', 'y'), IND(C, 'N', 'z')))
w.qed([w.s([ex, al], 'jca', '( %s -> ( E. y e. %s X = %s /\\ A. y e. %s A. z e. %s ( ( X = %s /\\ X = %s ) -> y = z ) ) )' % (HC, DB(C), IND(C, 'N', 'y'), DB(C), DB(C), IND(C, 'N', 'y'), IND(C, 'N', 'z'))), r4], 'sylibr', '( %s -> %s )' % (HC, EU)); run(w)

# ---- dchrprimcl, dchrprimind
w = W('dchrprimcl', 'The primitive character is a character mod the conductor.')
w.qed([w.s([], 'dchrprimval', '( %s -> %s = %s )' % (HC, P, PB)), w.s([w.s([], 'dchrprimeu', '( %s -> %s )' % (HC, EU)), w.inst('riotacl')], 'syl', '( %s -> %s e. %s )' % (HC, PB, DB(C)))], 'eqeltrd', '( %s -> %s e. %s )' % (HC, P, DB(C))); run(w)
w = W('dchrprimind', 'The primitive character induces X (Mathlib changeLevel_primitiveCharacter).')
sb = w.s([w.s([], 'fveq2', '( y = %s -> %s = %s )' % (P, IND(C, 'N', 'y'), IND(C, 'N', P)))], 'eqeq2d', '( y = %s -> ( X = %s <-> X = %s ) )' % (P, IND(C, 'N', 'y'), IND(C, 'N', P)))
r2 = w.s([w.s([], 'dchrprimcl', '( %s -> %s e. %s )' % (HC, P, DB(C))), w.s([], 'dchrprimeu', '( %s -> %s )' % (HC, EU)), w.s([sb], 'riota2', '( ( %s e. %s /\\ %s ) -> ( X = %s <-> %s = %s ) )' % (P, DB(C), EU, IND(C, 'N', P), PB, P))], 'syl2anc', '( %s -> ( X = %s <-> %s = %s ) )' % (HC, IND(C, 'N', P), PB, P))
pv = w.s([w.s([], 'dchrprimval', '( %s -> %s = %s )' % (HC, P, PB))], 'eqcomd', '( %s -> %s = %s )' % (HC, PB, P))
w.qed([w.s([pv, r2], 'mpbird', '( %s -> X = %s )' % (HC, IND(C, 'N', P)))], 'eqcomd', '( %s -> %s = X )' % (HC, IND(C, 'N', P))); run(w)

# ---- dchrprimvalz
HV = '( %s /\\ A e. ZZ /\\ %s )' % (HC, COP('A', 'N'))
w = W('dchrprimvalz', 'The primitive character agrees with X at every integer coprime to the level (Mathlib primitiveCharacter_apply_of_isCoprime; PsiTheta primitiveCharacter_natCast_eq_of_coprime).')
hc = w.s([], 'simp1', '( %s -> %s )' % (HV, HC)); n = w.s([hc], 'simpld', '( %s -> N e. NN )' % HV); a = w.s([], 'simp2', '( %s -> A e. ZZ )' % HV); c = w.s([], 'simp3', '( %s -> %s )' % (HV, COP('A', 'N')))
cn, cd = hcond(w, HV, hc)
pc = w.s([hc, w.inst('dchrprimcl')], 'syl', '( %s -> %s e. %s )' % (HV, P, DB(C)))
hx = w.s([w.s([cn, n, cd], '3jca', '( %s -> ( %s e. NN /\\ N e. NN /\\ %s || N ) )' % (HV, C, C)), pc], 'jca', '( %s -> ( ( %s e. NN /\\ N e. NN /\\ %s || N ) /\\ %s e. %s ) )' % (HV, C, C, P, DB(C)))
v = w.s([hx, a, c, w.inst('dchrindval1')], 'syl3anc', '( %s -> %s = %s )' % (HV, EV(IND(C, 'N', P), 'N', 'A'), EV(P, C, 'A')))
xe = w.s([w.s([hc, w.inst('dchrprimind')], 'syl', '( %s -> %s = X )' % (HV, IND(C, 'N', P)))], 'fveq1d', '( %s -> %s = %s )' % (HV, EV(IND(C, 'N', P), 'N', 'A'), EV('X', 'N', 'A')))
w.qed([v, xe], 'eqtr3d', '( %s -> %s = %s )' % (HV, EV(P, C, 'A'), EV('X', 'N', 'A'))); run(w)

# ---- dchrprimprim: the primitive character is primitive
C2 = COND(C, P)
w = W('dchrprimprim', 'The primitive character is primitive: its conductor is the conductor of X (Mathlib primitiveCharacter_isPrimitive).')
n = w.s([], 'simpl', '( %s -> N e. NN )' % HC); x = w.s([], 'simpr', '( %s -> X e. %s )' % (HC, DB('N')))
cn, cd = hcond(w, HC, w.s([], 'id', '( %s -> %s )' % (HC, HC)))
pc = w.s([], 'dchrprimcl', '( %s -> %s e. %s )' % (HC, P, DB(C))); hcp = w.s([cn, pc], 'jca', '( %s -> ( %s e. NN /\\ %s e. %s ) )' % (HC, C, P, DB(C)))
c2n = w.s([hcp, w.inst('dchrcondnn')], 'syl', '( %s -> %s e. NN )' % (HC, C2)); c2d = w.s([hcp, w.inst('dchrconddvdn')], 'syl', '( %s -> %s || %s )' % (HC, C2, C))
le1 = w.s([w.s([w.s([c2n], 'nnzd', '( %s -> %s e. ZZ )' % (HC, C2)), cn, w.inst('dvdsle')], 'syl2anc', '( %s -> ( %s || %s -> %s <_ %s ) )' % (HC, C2, C, C2, C)), c2d], 'mpd', '( %s -> %s <_ %s )' % (HC, C2, C))
c2N = w.s([w.s([c2n], 'nnzd', '( %s -> %s e. ZZ )' % (HC, C2)), w.s([cn], 'nnzd', '( %s -> %s e. ZZ )' % (HC, C)), w.s([n], 'nnzd', '( %s -> N e. ZZ )' % HC), c2d, cd], 'dvdstrd', '( %s -> %s || N )' % (HC, C2))
ex = w.s([hcp, w.inst('dchrcondex')], 'syl', '( %s -> E. y e. %s %s = %s )' % (HC, DB(C2), P, IND(C2, C, 'y')))
A2 = '( %s /\\ ( y e. %s /\\ %s = %s ) )' % (HC, DB(C2), P, IND(C2, C, 'y'))
yd = w.s([], 'simprl', '( %s -> y e. %s )' % (A2, DB(C2))); pe = w.s([], 'simprr', '( %s -> %s = %s )' % (A2, P, IND(C2, C, 'y')))
tr = w.s([w.s([w.s([c2n], 'adantr', '( %s -> %s e. NN )' % (A2, C2)), w.s([cn], 'adantr', '( %s -> %s e. NN )' % (A2, C)), w.s([n], 'adantr', '( %s -> N e. NN )' % A2)], '3jca', '( %s -> ( %s e. NN /\\ %s e. NN /\\ N e. NN ) )' % (A2, C2, C)), w.s([w.s([c2d], 'adantr', '( %s -> %s || %s )' % (A2, C2, C)), w.s([cd], 'adantr', '( %s -> %s || N )' % (A2, C))], 'jca', '( %s -> ( %s || %s /\\ %s || N ) )' % (A2, C2, C, C)), yd, w.inst('dchrindtr')], 'syl3anc', '( %s -> %s = %s )' % (A2, IND(C, 'N', IND(C2, C, 'y')), IND(C2, 'N', 'y')))
xe = w.s([w.s([w.s([w.s([], 'dchrprimind', '( %s -> %s = X )' % (HC, IND(C, 'N', P)))], 'adantr', '( %s -> %s = X )' % (A2, IND(C, 'N', P))), w.s([pe], 'fveq2d', '( %s -> %s = %s )' % (A2, IND(C, 'N', P), IND(C, 'N', IND(C2, C, 'y'))))], 'eqtr3d', '( %s -> X = %s )' % (A2, IND(C, 'N', IND(C2, C, 'y')))), tr], 'eqtrd', '( %s -> X = %s )' % (A2, IND(C2, 'N', 'y')))
sb = w.s([w.s([w.s([], 'fveq2', '( z = y -> %s = %s )' % (IND(C2, 'N', 'z'), IND(C2, 'N', 'y')))], 'eqeq2d', '( z = y -> ( X = %s <-> X = %s ) )' % (IND(C2, 'N', 'z'), IND(C2, 'N', 'y')))], 'rspcev', '( ( y e. %s /\\ X = %s ) -> E. z e. %s X = %s )' % (DB(C2), IND(C2, 'N', 'y'), DB(C2), IND(C2, 'N', 'z')))
ez = w.s([yd, xe, sb], 'syl2anc', '( %s -> E. z e. %s X = %s )' % (A2, DB(C2), IND(C2, 'N', 'z')))
ez2 = w.s([ex, ez], 'rexlimddv', '( %s -> E. z e. %s X = %s )' % (HC, DB(C2), IND(C2, 'N', 'z')))
iz = w.s([], 'id', '( z = y -> z = y )'); czy, nzy = w.wcongr('X = %s' % IND(C2, 'N', 'z'), {'z': 'y'}, 'z = y', {'z': iz})
ey = w.s([ez2, w.s([czy], 'cbvrexvw', '( E. z e. %s X = %s <-> E. y e. %s X = %s )' % (DB(C2), IND(C2, 'N', 'z'), DB(C2), IND(C2, 'N', 'y')))], 'sylib', '( %s -> E. y e. %s X = %s )' % (HC, DB(C2), IND(C2, 'N', 'y')))
mem = w.s([w.s([c2n, w.s([c2N, ey], 'jca', '( %s -> %s )' % (HC, BODY(C2, 'N', 'X')))], 'jca', '( %s -> ( %s e. NN /\\ %s ) )' % (HC, C2, BODY(C2, 'N', 'X'))), w.s([], 'dchrcondel', '( %s e. %s <-> ( %s e. NN /\\ %s ) )' % (C2, CS, C2, BODY(C2, 'N', 'X')))], 'sylibr', '( %s -> %s e. %s )' % (HC, C2, CS))
le2 = w.s([w.s([], 'id', '( %s -> %s )' % (HC, HC)), mem, w.inst('dchrcondle')], 'syl2anc', '( %s -> %s <_ %s )' % (HC, C, C2))
w.qed([w.s([le1, le2], 'jca', '( %s -> ( %s <_ %s /\\ %s <_ %s ) )' % (HC, C2, C, C, C2)), w.s([w.s([c2n], 'nnred', '( %s -> %s e. RR )' % (HC, C2)), w.s([cn], 'nnred', '( %s -> %s e. RR )' % (HC, C)), w.inst('letri3')], 'syl2anc', '( %s -> ( %s = %s <-> ( %s <_ %s /\\ %s <_ %s ) ) )' % (HC, C2, C, C2, C, C, C2))], 'mpbird', '( %s -> %s = %s )' % (HC, C2, C)); run(w)

# ---- dchrprimne1b
ONEC = ONE(C); ONE1 = ONE('1')
w = W('dchrprimne1b', 'The primitive character is trivial iff X is trivial (LConvexityCorollaries: the primitive character of a nontrivial character is nontrivial).')
n = w.s([], 'simpl', '( %s -> N e. NN )' % HC); x = w.s([], 'simpr', '( %s -> X e. %s )' % (HC, DB('N')))
cn, cd = hcond(w, HC, w.s([], 'id', '( %s -> %s )' % (HC, HC)))
pi = w.s([], 'dchrprimind', '( %s -> %s = X )' % (HC, IND(C, 'N', P)))
A1 = '( %s /\\ %s = %s )' % (HC, P, ONEC)
f1 = w.s([w.s([w.s([], 'simpr', '( %s -> %s = %s )' % (A1, P, ONEC))], 'fveq2d', '( %s -> %s = %s )' % (A1, IND(C, 'N', P), IND(C, 'N', ONEC))), w.s([w.s([cn], 'adantr', '( %s -> %s e. NN )' % (A1, C)), w.s([n], 'adantr', '( %s -> N e. NN )' % A1), w.s([cd], 'adantr', '( %s -> %s || N )' % (A1, C)), w.inst('dchrind1')], 'syl3anc', '( %s -> %s = %s )' % (A1, IND(C, 'N', ONEC), ONE('N')))], 'eqtrd', '( %s -> %s = %s )' % (A1, IND(C, 'N', P), ONE('N')))
f2 = w.s([w.s([pi], 'adantr', '( %s -> %s = X )' % (A1, IND(C, 'N', P))), f1], 'eqtr3d', '( %s -> X = %s )' % (A1, ONE('N')))
f3 = w.s([f2], 'ex', '( %s -> ( %s = %s -> X = %s ) )' % (HC, P, ONEC, ONE('N')))
A2 = '( %s /\\ X = %s )' % (HC, ONE('N'))
c1 = w.s([w.s([], 'simpr', '( %s -> X = %s )' % (A2, ONE('N'))), w.s([w.s([], 'dchrcondeq1', '( %s -> ( X = %s <-> %s = 1 ) )' % (HC, ONE('N'), C))], 'adantr', '( %s -> ( X = %s <-> %s = 1 ) )' % (A2, ONE('N'), C))], 'mpbid', '( %s -> %s = 1 )' % (A2, C))
db1 = w.s([w.s([c1], 'fveq2d', '( %s -> ( DChr ` %s ) = ( DChr ` 1 ) )' % (A2, C))], 'fveq2d', '( %s -> %s = %s )' % (A2, DB(C), DB('1')))
p1 = w.s([w.s([w.s([], 'dchrprimcl', '( %s -> %s e. %s )' % (HC, P, DB(C)))], 'adantr', '( %s -> %s e. %s )' % (A2, P, DB(C))), db1], 'eleqtrd', '( %s -> %s e. %s )' % (A2, P, DB('1')))
p2 = w.s([p1, w.inst('dchr1lev')], 'syl', '( %s -> %s = %s )' % (A2, P, ONE1))
o1 = w.s([w.s([c1], 'fveq2d', '( %s -> ( DChr ` %s ) = ( DChr ` 1 ) )' % (A2, C))], 'fveq2d', '( %s -> %s = %s )' % (A2, ONEC, ONE1))
b1 = w.s([p2, o1], 'eqtr4d', '( %s -> %s = %s )' % (A2, P, ONEC))
w.qed([f3, w.s([b1], 'ex', '( %s -> ( X = %s -> %s = %s ) )' % (HC, ONE('N'), P, ONEC))], 'impbid', '( %s -> ( %s = %s <-> X = %s ) )' % (HC, P, ONEC, ONE('N'))); run(w)

# ---- dchrprimsfi: the set of primitive characters mod F is finite
PS = '{ y e. %s | %s = F }' % (DB('F'), COND('F', 'y'))
w = W('dchrprimsfi', 'The set of primitive characters mod F (LargeSieve primChars, a Finset) is finite.')
fi = w.s([w.s([w.s([], 'eqid', '( DChr ` F ) = ( DChr ` F )'), w.s([], 'eqid', '%s = %s' % (DB('F'), DB('F')))], 'dchrfi', '( F e. NN -> %s e. Fin )' % DB('F'))], 'id' if False else 'id', '( F e. NN -> %s e. Fin )' % DB('F'))
w.lines.pop()
fi = w.s([w.s([], 'eqid', '( DChr ` F ) = ( DChr ` F )'), w.s([], 'eqid', '%s = %s' % (DB('F'), DB('F')))], 'dchrfi', '( F e. NN -> %s e. Fin )' % DB('F'))
w.qed([fi, w.s([w.s([], 'ssrab2', '%s C_ %s' % (PS, DB('F')))], 'a1i', '( F e. NN -> %s C_ %s )' % (PS, DB('F'))), w.inst('ssfi')], 'syl2anc', '( F e. NN -> %s e. Fin )' % PS); run(w)

# ---- dchrprimindinj: inducing primitive characters to a common level is injective on (level, character)
HI = '( ( Q e. NN /\\ F e. NN /\\ G e. NN ) /\\ ( F || Q /\\ G || Q ) /\\ ( ( X e. %s /\\ %s = F ) /\\ ( Z e. %s /\\ %s = G ) ) )' % (DB('F'), COND('F', 'X'), DB('G'), COND('G', 'Z'))
YF = IND('F', 'Q', 'X'); YG = IND('G', 'Q', 'Z')
w = W('dchrprimindinj', 'Two primitive characters, mod F and mod G, induce the same character mod Q only if F = G and the characters are equal (the injectivity behind LargeSieve fiber_block_le: conductor_changeLevel and changeLevel_injective).')
q = w.s([w.s([], 'simp1', '( %s -> ( Q e. NN /\\ F e. NN /\\ G e. NN ) )' % HI)], 'simp1d', '( %s -> Q e. NN )' % HI)
