h3u = w.s([u, uv, du], '3jca', '( %s -> ( U e. NN /\\ %s e. NN /\\ U || %s ) )' % (HP, UV, UV)); h3v = w.s([v, uv, dv], '3jca', '( %s -> ( V e. NN /\\ %s e. NN /\\ V || %s ) )' % (HP, UV, UV))
yud = w.s([w.s([h3u, x], 'jca', '( %s -> ( ( U e. NN /\\ %s e. NN /\\ U || %s ) /\\ X e. %s ) )' % (HP, UV, UV, DB('U'))), w.inst('dchrindcl')], 'syl', '( %s -> %s e. %s )' % (HP, YU, DB(UV)))
yvd = w.s([w.s([h3v, izd], 'jca', '( %s -> ( ( V e. NN /\\ %s e. NN /\\ V || %s ) /\\ %s e. %s ) )' % (HP, UV, UV, IZ, DB('V'))), w.inst('dchrindcl')], 'syl', '( %s -> %s e. %s )' % (HP, YV, DB(UV)))
guv = w.s([w.s([uv, w.s([w.s([], 'eqid', '( DChr ` %s ) = ( DChr ` %s )' % (UV, UV))], 'dchrabl', '( %s e. NN -> ( DChr ` %s ) e. Abel )' % (UV, UV))], 'syl', '( %s -> ( DChr ` %s ) e. Abel )' % (HP, UV))], 'ablgrpd', '( %s -> ( DChr ` %s ) e. Grp )' % (HP, UV))
