hi = w.s([w.s([uv, u, v], '3jca', '( %s -> ( %s e. NN /\\ U e. NN /\\ V e. NN ) )' % (HP, UV)), w.s([du, dv], 'jca', '( %s -> ( U || %s /\\ V || %s ) )' % (HP, UV, UV)), w.s([w.s([x, xp], 'jca', '( %s -> ( X e. %s /\\ %s = U ) )' % (HP, DB('U'), COND('U', 'X'))), w.s([z, zp], 'jca', '( %s -> ( Z e. %s /\\ %s = V ) )' % (HP, DB('V'), COND('V', 'Z')))], 'jca', '( %s -> ( ( X e. %s /\\ %s = U ) /\\ ( Z e. %s /\\ %s = V ) ) )' % (HP, DB('U'), COND('U', 'X'), DB('V'), COND('V', 'Z')))], '3jca', '( %s -> ( ( %s e. NN /\\ U e. NN /\\ V e. NN ) /\\ ( U || %s /\\ V || %s ) /\\ ( ( X e. %s /\\ %s = U ) /\\ ( Z e. %s /\\ %s = V ) ) ) )' % (HP, UV, UV, UV, DB('U'), COND('U', 'X'), DB('V'), COND('V', 'Z')))
inj = w.s([hi, w.inst('dchrprimindinj')], 'syl', '( %s -> ( %s = %s <-> ( U = V /\\ X = Z ) ) )' % (HP, YU, IND('V', UV, 'Z')))
